import { isMotionValue, mixNumber, motionValue } from "framer-motion/dom";
export function compareMin(a, b) {
    return a.layout.min - b.layout.min;
}
export function getValue(item) {
    return item.value;
}
export function checkReorder(order, value, offset, velocity) {
    const index = order.findIndex((item) => item.value === value);
    if (index === -1)
        return order;
    // Determine direction from velocity, fallback to offset if velocity is zero
    const direction = velocity !== 0 ? velocity : offset;
    // If no movement, return early
    if (!direction)
        return order;
    const nextOffset = direction > 0 ? 1 : -1;
    const nextItem = order[index + nextOffset];
    if (!nextItem)
        return order;
    const item = order[index];
    const nextLayout = nextItem.layout;
    const nextItemCenter = mixNumber(nextLayout.min, nextLayout.max, 0.5);
    if ((nextOffset === 1 && item.layout.max + offset > nextItemCenter) ||
        (nextOffset === -1 && item.layout.min + offset < nextItemCenter)) {
        return moveItem(order, index, index + nextOffset);
    }
    return order;
}
export function moveItem([...arr], fromIndex, toIndex) {
    const startIndex = fromIndex < 0 ? arr.length + fromIndex : fromIndex;
    if (startIndex >= 0 && startIndex < arr.length) {
        const endIndex = toIndex < 0 ? arr.length + toIndex : toIndex;
        const [item] = arr.splice(fromIndex, 1);
        arr.splice(endIndex, 0, item);
    }
    return arr;
}
export function useDefaultMotionValue(value, defaultValue = 0) {
    return isMotionValue(value) ? value : motionValue(defaultValue);
}
